class Solution {
  public long subtreeInversionSum(int[][] edges, int[] nums, int k) {
    int n = nums.length;
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)];
    for (int[] e : edges) {
      to[start[e[0]] + fill[e[0]]++] = e[1];
      to[start[e[1]] + fill[e[1]]++] = e[0];
    }
    int[] order = new int[n], par = new int[n];
    par[0] = -1;
    int head = 0, tail = 0;
    order[tail++] = 0;
    while (head < tail) {
      int u = order[head++];
      for (int p = start[u]; p < start[u + 1]; p++) {
        if (to[p] != par[u]) {
          par[to[p]] = u;
          order[tail++] = to[p];
        }
      }
    }
    int D = k + 1;
    long[] f = new long[n * D * 2];
    for (int idx = n - 1; idx >= 0; idx--) {
      int u = order[idx];
      for (int flip = 0; flip < 2; flip++) {
        int sign = flip == 0 ? 1 : -1;
        for (int d = 1; d <= k; d++) {
          long keep = (long) sign * nums[u];
          int nd = Math.min(d + 1, k);
          for (int p = start[u]; p < start[u + 1]; p++) {
            int c = to[p];
            if (c != par[u]) keep += f[(c * D + nd) * 2 + flip];
          }
          long best = keep;
          if (d == k) {
            long inv = (long) -sign * nums[u];
            for (int p = start[u]; p < start[u + 1]; p++) {
              int c = to[p];
              if (c != par[u]) inv += f[(c * D + 1) * 2 + (1 - flip)];
            }
            best = Math.max(best, inv);
          }
          f[(u * D + d) * 2 + flip] = best;
        }
      }
    }
    return f[(0 * D + k) * 2];
  }
}
